```java
class Probe {
    /** Precondition: s is not null and c has exactly one character. */
    public static int mystery(String s, String c) {
        int n = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.substring(i, i + 1).equals(c)) {
                n++;
            }
        }
        return n;
    }
}
```

